import functools, time

def timed(func):
    # TODO: return a wrapper that times `func`, prints "<name> took <ms> ms",
    # returns func's result unchanged, and preserves func's metadata via functools.wraps.
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

