        check_true("row-count-preserved", len(out) == len(trades), detail=f"len={len(out)}")
    except Exception as e:
        check_true("row-count-preserved", False, f"EXC:{e}")

    # first-trade-backward: 09:30:01 trade gets the 09:30:00 quote (last at/before)
    try:
        out = attach_prevailing_quote(trades, quotes).set_index("time")
        r = out.loc[pd.Timestamp("2024-01-02 09:30:01")]
        check_true("first-trade-prevailing", (r["bid"] == 99.9 and r["ask"] == 100.1),
                   detail=f"bid={r['bid']} ask={r['ask']}")
    except Exception as e:
        check_true("first-trade-prevailing", False, f"EXC:{e}")

    # second-trade-backward: 09:30:05 gets 09:30:04 (1s old, within tolerance)
    try:
        out = attach_prevailing_quote(trades, quotes).set_index("time")
        r = out.loc[pd.Timestamp("2024-01-02 09:30:05")]
        check_true("second-trade-prevailing", (r["bid"] == 100.0 and r["ask"] == 100.2),
                   detail=f"bid={r['bid']} ask={r['ask']}")
    except Exception as e:
        check_true("second-trade-prevailing", False, f"EXC:{e}")

    # stale-rejected: 09:31:00 nearest prior quote is 30s old -> bid/ask NaN
    try:
        out = attach_prevailing_quote(trades, quotes).set_index("time")
        r = out.loc[pd.Timestamp("2024-01-02 09:31:00")]
        check_true("stale-quote-rejected", (pd.isna(r["bid"]) and pd.isna(r["ask"])),
                   detail=f"bid={r['bid']} ask={r['ask']}")
    except Exception as e:
        check_true("stale-quote-rejected", False, f"EXC:{e}")

    # no-lookahead: every attached quote time must be <= its trade time
    try:
        q2 = quotes.rename(columns={"time": "qtime"})
        merged = pd.merge_asof(trades.sort_values("time"), q2.sort_values("qtime"),
