        ok = (merged["qtime"].dropna() <= merged.loc[merged["qtime"].notna(), "time"]).all()
        check_true("no-lookahead", bool(ok), detail="all quote times <= trade time")
    except Exception as e:
        check_true("no-lookahead", False, f"EXC:{e}")

    # handles-unsorted-input: function sorts defensively, so shuffled input still works
    try:
        out = attach_prevailing_quote(trades.iloc[::-1].copy(), quotes.iloc[::-1].copy()).set_index("time")
